-- Generated by `scrapagents generate-dbt` from configs/contracts/world_bank/opportunities.yml. Do not edit: change the contract and regenerate.
{{ config(tags=["source_world_bank"]) }}

with source as (

    select * from {{ source('world_bank', 'opportunities') }}

),

records as (

    select
        payload as record,
        _batch_id::text as bronze_batch_id,
        _record_hash as bronze_record_hash,
        _landing_uri as bronze_landing_uri,
        _ingested_at as bronze_ingested_at
    from source

)

select
    (record ->> 'id')::text as id,
    (record ->> 'notice_type')::text as notice_type,
    (record ->> 'notice_status')::text as notice_status,
    (record ->> 'noticedate')::text as noticedate,
    (record ->> 'submission_date')::timestamptz as submission_date,
    (record ->> 'submission_deadline_date')::timestamptz as submission_deadline_date,
    (record ->> 'project_id')::text as project_id,
    (record ->> 'project_name')::text as project_name,
    (record ->> 'project_ctry_name')::text as project_ctry_name,
    (record ->> 'bid_reference_no')::text as bid_reference_no,
    (record ->> 'bid_description')::text as bid_description,
    (record ->> 'procurement_group')::text as procurement_group,
    (record ->> 'procurement_method_code')::text as procurement_method_code,
    (record ->> 'procurement_method_name')::text as procurement_method_name,
    (record ->> 'notice_lang_name')::text as notice_lang_name,
    (record ->> 'contact_organization')::text as contact_organization,
    (record ->> 'contact_email')::text as contact_email,
    (record ->> 'notice_text')::text as notice_text,
    (record ->> 'source_url')::text as source_url,
    bronze_batch_id,
    bronze_record_hash,
    bronze_landing_uri,
    bronze_ingested_at
from records
